// ---- canonical value encoding: RLP over typed nodes, and the flat integrity digest ----

export type CanonicalValueError = Tagged<"non_finite_number" | "unsupported_type" | "invalid_utf8">;
type Rlp = Uint8Array | readonly Rlp[];
