  const validators = [...membersOf(q).keys()].map(signerId);
  const [ceo, ...successors] = validators;
  const heavierFirst = (l: string, r: string): number =>
    asc(sharesOf(q, r), sharesOf(q, l)) || validators.indexOf(l) - validators.indexOf(r) || asc(l, r);
