  "htlc_resolve",
  "request_collateral",
  "swap_offer",
  "swap_cancel_request",
  "swap_resolve",
  "cross_pull_lock",
  "cross_pull_close",
  "lending_fund",
  "lending_borrow_request",
  "lending_repay",
  "lending_credit",
  "lending_close_request",
  "lending_close_payout",
  "rebalance_policy",
