  map(defaultRebalanceBaseFee(Number(tokenId)), (baseFee): AccountTx => ({
    type: "rebalance_policy",
    tokenId,
    policyVersion: config.policyVersion,
    baseFee,
    liquidityFeeBps: config.rebalanceLiquidityFeeBps,
    gasFee: 0n,
  }));
