  const parts = all({
    id: mapErr(accountId(state.id, from), (): EntityError => ({ _tag: "self_account" })),
    policies: traverse(DEFAULT_ACCOUNT_TOKEN_IDS, (t) =>
      map(rebalanceDefaults(state.jurisdictionConfig, Number(t)), (p) => [Number(t), p] as const)),
  });
