  "hashlock",
  "maxSenderDebit",
  "nextHopEntityId",
  "recipientAmount",
  "revealBeforeHeight",
  "route",
  "senderLockAmount",
  "startedAtMs",
  "targetEntityId",
  "timelock",
  "tokenId",
  "totalFee",
  "txHash",
