      const frame = `frameHeight=${replica.frame.height}:frameHash=${frameHash}`;
      return txErr(`J_HISTORY_SIGNED_LOCK_REORG:entity=${entityId}:signer=${signerId}:${frame}:jHeight=${height}`);
