  jevPipe(
    withRetiredJb(x, retired.jb),
    sayMaybe(retired.synced),
    broadcastWhen(retired.broadcast),
    sayWhen(retired.removed > 0, `🧹 Removed ${retired.removed} stale ${ops} op(s) for ${peer.slice(-4)}`),
  );
